import type { Application as ClientApplication, Entity as ClientEntity } from '../client/types.ts';

import type { E2eAddedApplicationProperties } from './application.ts';

export type { Config, Features, Options, Source } from '../client/types.ts';

/** The properties of an entity the e2e test frameworks share. */
export type E2eAddedEntityProperties = {
  /** An instance of the entity for the e2e tests, with its required fields not generated by the database. */
  e2eTestEntitySample?: Record<string, any>;
  /** An instance of the entity for the e2e tests, with its fields not generated by the database. */
  e2eTestEntity?: Record<string, any>;
};

export type Entity = ClientEntity & E2eAddedEntityProperties;

export type Application<E extends Entity = Entity> = ClientApplication<E> & E2eAddedApplicationProperties;
